import java.io.Serializable;

public class JobEvent implements Serializable {
    public long timestamp;
    public long jobId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public String jobName;
    public String logicalJobName;
    public int missingInfo;

    public JobEvent() {}

    public JobEvent(long timestamp, long jobId, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public static JobEvent fromString(String line) {
        String[] tokens = line.split(",");
        JobEvent event = new JobEvent();
        try {
            event.timestamp = Long.parseLong(tokens[0]);
            event.missingInfo = tokens[1].isEmpty() ? 0 : Integer.parseInt(tokens[1]);
            event.jobId = Long.parseLong(tokens[2]);
            event.eventType = Integer.parseInt(tokens[3]);
            event.userName = tokens[4];
            event.schedulingClass = tokens[5].isEmpty() ? 0 : Integer.parseInt(tokens[5]);
            event.jobName = tokens[6];
            event.logicalJobName = tokens[7];
        } catch (Exception e) {
            // In case of parsing error or incomplete line, return null or handle appropriately
            // For now, simple error handling
            System.err.println("Error parsing JobEvent: " + line);
            return null;
        }
        return event;
    }

    @Override
    public String toString() {
        return "JobEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", eventType=" + eventType +
                '}';
    }
}

