package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Task Events
        DataStream<TaskEvent> tasks;
        if (taskEvents != null) {
            tasks = env.addSource(taskEvents);
        } else {
            tasks = env.readTextFile(taskInput)
                    .map(TaskEvent::fromString)
                    .filter(e -> e != null);
        }

        DataStream<TaskEvent> tasksWithTimestamps = tasks.assignTimestampsAndWatermarks(
                WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                        .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000) // micro to milli
        );

        // Job Events
        DataStream<JobEvent> jobs;
        if (jobEvents != null) {
            jobs = env.addSource(jobEvents);
        } else {
            jobs = env.readTextFile(jobInput)
                    .map(JobEvent::fromString)
                    .filter(e -> e != null);
        }

        DataStream<JobEvent> jobsWithTimestamps = jobs.assignTimestampsAndWatermarks(
                WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                        .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
        );

        // 1. Calculate stages (Task Sessions)
        // Filter SUBMIT (0)
        DataStream<Tuple2<Long, Integer>> stageCounts = tasksWithTimestamps
                .filter(t -> t.eventType == 0)
                .keyBy(t -> t.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .process(new ProcessWindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow>() {
                    @Override
                    public void process(Long key, Context context, Iterable<TaskEvent> elements, Collector<Tuple2<Long, Integer>> out) {
                        int count = 0;
                        for (TaskEvent ignored : elements) {
                            count++;
                        }
                        out.collect(Tuple2.of(key, count));
                    }
                });

        // 2. Filter Finished Jobs (FAIL=3, FINISH=4, KILL=5, LOST=6)
        DataStream<JobEvent> finishedJobs = jobsWithTimestamps
                .filter(j -> j.eventType == 3 || j.eventType == 4 || j.eventType == 5 || j.eventType == 6);

        // 3. Connect and find max stage at end
        DataStream<Tuple2<Long, Integer>> result = stageCounts.connect(finishedJobs)
                .keyBy(t -> t.f0, j -> j.jobId)
                .process(new MaxStageProcessFunction(sesssize));

        // Output
        if (out != null) {
            result.map(Tuple2::toString).addSink(out);
        } else {
            result.map(Tuple2::toString).writeAsText(outputPath).setParallelism(1);
        }

        env.execute("LongestSessionPerJob");
    }

    public static class MaxStageProcessFunction extends KeyedCoProcessFunction<Long, Tuple2<Long, Integer>, JobEvent, Tuple2<Long, Integer>> {
        private ValueState<Integer> maxStageSize;
        private ValueState<Boolean> isFinished;
        private final int sessionGapSeconds;

        public MaxStageProcessFunction(int sessionGapSeconds) {
            this.sessionGapSeconds = sessionGapSeconds;
        }

        @Override
        public void open(Configuration parameters) {
            maxStageSize = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageSize", Integer.class));
            isFinished = getRuntimeContext().getState(new ValueStateDescriptor<>("isFinished", Boolean.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer currentMax = maxStageSize.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxStageSize.update(value.f1);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            isFinished.update(true);
            // Register timer for cleanup/emit.
            // Wait session gap + small buffer (e.g. 1 sec) to ensure any pending windows close.
            long timerTime = ctx.timestamp() + (sessionGapSeconds * 1000L) + 1000;
            ctx.timerService().registerEventTimeTimer(timerTime);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(isFinished.value())) {
                Integer max = maxStageSize.value();
                if (max == null) max = 0; // Job finished but no tasks (or no stages).
                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                isFinished.clear();
                maxStageSize.clear();
            }
        }
    }

}

